const fs=require('fs');
const html=fs.readFileSync('/var/tmp/bench/ws-zDJRKwWw/web-reactiva-craft.html','utf8');
const mB=html.match(/const BASE=(\[[\s\S]*?\n\]);/);
const mR=html.match(/const R=(\[[\s\S]*?\n\]);/);
const mW=html.match(/const WILD=(\[[\s\S]*?\n\]);/);
eval('var BASE='+mB[1]);eval('var R='+mR[1]);eval('var WILD='+mW[1]);
let ok=true;
const key=(a,b)=>a<b?a+'|'+b:b+'|'+a;
const map=new Map();
for(const[r,e,a,b]of R){
  if(!(r&&e&&a&&b)){ok=false;console.log('BAD ENTRY',JSON.stringify(r))}
  const k=key(a,b);
  if(map.has(k)){ok=false;console.log('DUP PAIR',k,'->',map.get(k),'and',r)}
  map.set(k,r);
}
const names=new Set(BASE.map(b=>b[0]));
for(const[r]of R)names.add(r);
let changed=true;
while(changed){
  changed=false;
  for(const[r,,,]of R){}
  for(const e of R){const[r,,a,b]=e;
    if(names.has(a)&&names.has(b)&&!names.has(r)){names.add(r);changed=true}
  }
}
const broken=R.filter(([r,,a,b])=>!names.has(a)||!names.has(b));
if(broken.length){ok=false;for(const e of broken)console.log('UNREACHABLE INPUT:',e[2],'+',e[3],'->',e[0])}
const baseSet=new Set(BASE.map(b=>b[0]));
const resNames=R.map(r=>r[0]);
for(const[wn]of WILD){
  if(names.has(wn)){ok=false;console.log('WILD NAME COLLIDES:',wn)}
}
const dupRes=new Set();for(const n of resNames){if(dupRes.has(n))console.log('dup result name (ok but check):',n);dupRes.add(n)}
const emojiBad=[...BASE,...R,...WILD].filter(x=>!x[1]||x[1].length<1);
if(emojiBad.length){ok=false;console.log('MISSING EMOJI',emojiBad)}
console.log('recipes:',R.length,'| unique pairs:',map.size,'| reachable results:',names.size,'| wildcards:',WILD.length);
console.log(ok?'CHECK OK':'CHECK FAILED');
const script=html.match(/<script>([\s\S]*?)<\/script>/)[1];
fs.writeFileSync('/tmp/opencode/g.js',script);
EOF
node /tmp/opencode/check.js && node --check /tmp/opencode/g.js && echo "SYNTAX OK"

